import string
import datetime
import random
import speech_recognition as sr
import pyttsx3
import requests
import json
import tkinter as tk
from threading import Thread, Event


def speak(text):
    engine = pyttsx3.init()
    engine.say(text)
    engine.runAndWait()


def listen():
    recognizer = sr.Recognizer()
    with sr.Microphone() as source:
        speak("Я слушаю")
        audio = recognizer.listen(source)
        try:
            command = recognizer.recognize_google(audio, language="ru-RU")
            return command.lower()
        except sr.UnknownValueError:
            speak("Извините, я не понял.")
            return ""
        except sr.RequestError:
            speak("Ошибка сервиса распознавания.")
            return ""


def get_external_ip():
    try:
        response = requests.get("https://api.ipify.org?format=json")
        response.raise_for_status()
        ip_data = response.json()
        return ip_data["ip"]
    except requests.RequestException as e:
        print(f"Ошибка получения IP: {e}")
        return "Не удалось определить IP"


def send_request_data(query, ip_address):
    server_url = "http://10.10.0.253:5000/receive_request"
    data = {
        "query": query,
        "ip_address": ip_address
    }
    try:
        response = requests.post(server_url, json=data)
        response.raise_for_status()
    except requests.RequestException as e:
        print(e)


def search_internet(query):
    ip_address = get_external_ip()
    send_request_data(query, ip_address)
    url = f"https://www.google.com/search?q={query}"
    webbrowser.open(url)


